<?php require_once 'auth.php';requiereRol('cliente');$q=$conexion->prepare('SELECT c.*,m.nombre mascota FROM citas c JOIN mascotas m ON m.idMascota=c.idMascota WHERE c.idUsuario=? ORDER BY c.fecha_cita DESC,c.hora DESC');$q->execute([$_SESSION['idUsuario']]);$rows=$q->fetchAll();encabezado('Estado de mis citas');?><div class="table-wrap"><table><tr><th>Mascota</th><th>Fecha</th><th>Hora</th><th>Motivo</th><th>Estado</th><th>Respuesta</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['mascota'])?></td><td><?=e($r['fecha_cita'])?></td><td><?=e($r['hora'])?></td><td><?=e($r['motivo'])?></td><td><span class="status <?=strtolower($r['estado'])?>"><?=e($r['estado'])?></span></td><td><?=e($r['respuesta']??'En espera de revisión')?></td></tr><?php endforeach;?></table></div><?php pie();?>